package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.Try
import io.circe._
import io.circe.syntax._

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Protocols (Traits)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(newMeta: (String, Any)*): Token = {
    copy(metadata = metadata ++ newMeta)
  }
}

class MutableTokenBatch {
  private val _tokens = scala.collection.mutable.ListBuffer[Token]()
  private var _processed: Boolean = False

  // Scala convention: use boolean literal false/true
  private val False = false
  private val True = true

  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = True
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): List[String] = {
    _items.map(func).toList
  }

  def size: Int = _items.size
}

class TokenSink[-T] {
  private val _received = scala.collection.mutable.ListBuffer[Any]()

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](default: T) {
  private var _value: T = default

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
    encoding: String = "utf-8", 
    normalizer: String => String = identity
) extends BaseTokenizer[Any] { 

  def tokenize(value: Any): Token = {
    val strValue = value match {
      case bytes: Array[Byte] => new String(bytes, encoding)
      case s: String => s
      case other => other.toString
    }

    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  def tokenize(value: Any): Token = {
    val (strValue, originalType) = value match {
      case d: BigDecimal => (f"$d%.${precision}f", "BigDecimal")
      case d: Double => (f"$d%.${precision}f", "Float") // Python float matches Double
      case f: Float => (f"$f%.${precision}f", "Float")
      case i: Int => (i.toString, "Int")
      case l: Long => (l.toString, "Int") // Python int is arbitrary precision, closest to BigInt or Long
      case n: Number => (n.toString, n.getClass.getSimpleName)
      case other => (other.toString, other.getClass.getSimpleName)
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

class TemporalTokenizer(
    formatStr: Option[String] = None
) extends BaseTokenizer[Any] {

  private val ISO_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Any): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case _: LocalDateTime => ISO_FORMAT
        case _: LocalDate => DATE_FORMAT
        case _ => ISO_FORMAT
      }
    }

    val strValue = value match {
      case dt: java.time.temporal.TemporalAccessor => fmt.format(dt)
      case other => other.toString
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = {
    if (value == null) return tokenizeNull

    value match {
      case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
      case s: String => stringTokenizer.tokenize(s)
      case b: Array[Byte] => stringTokenizer.tokenize(b)
      case i: Int => numericTokenizer.tokenize(i)
      case l: Long => numericTokenizer.tokenize(l)
      case d: Double => numericTokenizer.tokenize(d)
      case f: Float => numericTokenizer.tokenize(f)
      case bd: BigDecimal => numericTokenizer.tokenize(bd)
      case dt: java.time.temporal.Temporal => temporalTokenizer.tokenize(dt)
      case None => tokenizeNull
      case Some(v) => tokenize(v)
      case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
    }
  }
}

// ============================================================================
